46	} from "../../lib/backend-list-params";
47	
48	export type BoardContextValue = {
49	  workspaceDetail: WorkspaceDetail;
50	  features: ParsedFeature[];
51	  trackedFeatures: ParsedFeature[];
52	  loading: boolean;
53	  error: BoardLoadError | null;
