60	  openFeatureTab: (feature: ParsedFeature) => void;
61	  openFeatureTabNewSession: (feature: ParsedFeature) => void;
62	
63	  boardMode: BoardMode;
64	  setBoardMode: (mode: BoardMode) => void;
65	
66	  // Task Mode search/filter
67	  taskSearchQuery: string;
68	  setTaskSearchQuery: (query: string) => void;
69	  taskActiveFilters: ActiveFilters;
70	  setTaskActiveFilters: (filters: ActiveFilters) => void;
71	
72	  // Feature Mode search/filter
73	  featureSearchQuery: string;
74	  setFeatureSearchQuery: (query: string) => void;
75	  featureActiveFilters: FeatureActiveFilters;
76	  setFeatureActiveFilters: (filters: FeatureActiveFilters) => void;
77	
78	  // Aliases kept for existing Task Mode consumers
79	  searchQuery: string;
80	  setSearchQuery: (query: string) => void;
81	  activeFilters: ActiveFilters;
82	  setActiveFilters: (filters: ActiveFilters) => void;
83	
84	  expandedFeatureIds: Set<string>;
85	  toggleFeature: (featureId: string) => void;
86	
87	  // Backend search results (null = use workspace detail)
88	  backendTaskResults: ParsedFeature[] | null;
89	  backendFeatureResults: ParsedFeature[] | null;
90	  taskSearching: boolean;
91	  featureSearching: boolean;
92	  taskSearchError: BoardLoadError | null;
93	  featureSearchError: BoardLoadError | null;
94	
95	  // Pagination state per mode
96	  taskPage: number;
97	  setTaskPage: (page: number) => void;
98	  featurePage: number;
99	  setFeaturePage: (page: number) => void;
100	  taskPagination: PaginationMeta | null;
101	  featurePagination: PaginationMeta | null;
102	
103	  // Sort state per mode
104	  taskSort: string;
105	  setTaskSort: (sort: string) => void;
106	  featureSort: string;
107	  setFeatureSort: (sort: string) => void;
108	
109	  // Page size (limit) state per mode
110	  taskLimit: number;
111	  setTaskLimit: (limit: number) => void;
112	  featureLimit: number;
113	  setFeatureLimit: (limit: number) => void;
114	};
115	
116	const BoardContext = createContext<BoardContextValue | null>(null);
117	export type BoardTrackingContextValue = Pick<
118	  BoardContextValue,
119	  "trackedFeatures" | "openTaskTab" | "openTaskTabNewSession"
120	>;
121	
122	const BoardTrackingContext = createContext<BoardTrackingContextValue | null>(
123	  null,
124	);
125	
126	export type BoardProviderProps = {
127	  workspaceDetail: WorkspaceDetail;
128	  children: ReactNode;
129	};
130	
131	export function BoardProvider({
132	  workspaceDetail,
133	  children,
134	}: BoardProviderProps) {
135	  const { features, loading, error, reload } = useBoardData(
136	    workspaceDetail.id,
137	    {
138	      initialData: workspaceDetail,
139	    },
140	  );
141	  const { trackedFeatures, reload: reloadTracking } = usePullRequestTaskData(
142	    workspaceDetail.id,
143	  );
144	
145	  const {
146	    syncCurrentWorkspace,
147	    syncingWorkspace: syncing,
148	    syncError: wsyncError,
149	    openTaskTab: wsOpenTaskTab,
150	    openFeatureTab: wsOpenFeatureTab,
151	  } = useWorkspaceActionsContext();
152	
153	  const [boardMode, setBoardModeState] = useState<BoardMode>(
154	    () => getStoredBoardMode() ?? getDefaultBoardMode(),
155	  );
156	  const [taskSearchQuery, setTaskSearchQuery] = useState("");
157	  const [featureSearchQuery, setFeatureSearchQuery] = useState("");
158	  const [taskActiveFilters, setTaskActiveFiltersState] =
159	    useState<ActiveFilters>(() => ({
160	      statuses: getStoredStatusFilter() ?? getDefaultStatusFilter(),
161	    }));
162	  const [featureActiveFilters, setFeatureActiveFiltersState] =
163	    useState<FeatureActiveFilters>(() => ({
164	      statuses:
165	        getStoredFeatureStatusFilter() ?? getDefaultFeatureStatusFilter(),
166	    }));
167	  const [expandedFeatureIds, setExpandedFeatureIds] = useState<Set<string>>(
168	    () => new Set(),
169	  );
170	  const [taskPage, setTaskPage] = useState(1);
171	  const [featurePage, setFeaturePage] = useState(1);
172	  const [taskSort, setTaskSort] = useState(BOARD_DEFAULT_SORT);
173	  const [featureSort, setFeatureSort] = useState(BOARD_DEFAULT_SORT);
174	  const [taskLimit, setTaskLimit] = useState(BOARD_DEFAULT_LIMIT);
175	  const [featureLimit, setFeatureLimit] = useState(BOARD_DEFAULT_LIMIT);
176	
177	  // Build a map of feature backend ID -> feature lifecycle status from the
178	  // already-loaded features array.  Passed to useBackendTaskSearch so
179	  // adaptTaskSummariesToFeatures can set the correct feature lifecycle status
180	  // on each ParsedFeature instead of falling back to a task-derived value.
181	  const featureStatusMap = useMemo(() => {
182	    const map = new Map<string, string>();
183	    for (const f of features) {
184	      if (f.backendId && f.featureStatus) {
185	        map.set(f.backendId, f.featureStatus);
186	      }
187	    }
188	    return map as ReadonlyMap<string, string>;
189	  }, [features]);
190	
191	  // Backend search hooks
192	  const deferredTaskSearchQuery = useDeferredValue(taskSearchQuery);
193	  const deferredFeatureSearchQuery = useDeferredValue(featureSearchQuery);
194	  const trimmedTaskQuery = deferredTaskSearchQuery.trim();
195	
196	  // Backend search is active when either search text is present OR the status
197	  // filter is a non-default subset (not all statuses selected).  When every
198	  // status is selected there is no effective filter, so we fall back to the
199	  // workspace root payload.
200	  const taskStatusFilterActive =
201	    taskActiveFilters.statuses.length > 0 &&
202	    !isAllStatusFilterSelected(taskActiveFilters.statuses);
203	  const taskSearchActive =
204	    boardMode === "task" &&
205	    (trimmedTaskQuery.length > 0 || taskStatusFilterActive);
206	
207	  // Reset page to 1 when search query, filters, sort, or limit change
208	  const prevTaskQueryRef = useRef(trimmedTaskQuery);
209	  const prevTaskStatusRef = useRef(
210	    taskActiveFilters.statuses.join(","),
211	  );
212	  const prevTaskSortRef = useRef(taskSort);
213	  const prevTaskLimitRef = useRef(taskLimit);
214	  useEffect(() => {
215	    const currentStatus = taskActiveFilters.statuses.join(",");
216	    if (
217	      trimmedTaskQuery !== prevTaskQueryRef.current ||
218	      currentStatus !== prevTaskStatusRef.current ||
219	      taskSort !== prevTaskSortRef.current ||
220	      taskLimit !== prevTaskLimitRef.current
221	    ) {
222	      setTaskPage(1);
223	    }
224	    prevTaskQueryRef.current = trimmedTaskQuery;
225	    prevTaskStatusRef.current = currentStatus;
226	    prevTaskSortRef.current = taskSort;
227	    prevTaskLimitRef.current = taskLimit;
228	  }, [trimmedTaskQuery, taskActiveFilters.statuses, taskSort, taskLimit]);
229	
230	  const taskSearchParams = useMemo(() => {
231	    if (!taskSearchActive) return {};
232	
233	    const status = taskStatusFilterActive
234	      ? taskActiveFilters.statuses.join(",")
235	      : undefined;
236	
237	    return {
238	      title: trimmedTaskQuery || undefined,
239	      status,
240	      page: taskPage,
241	      limit: taskLimit,
242	      sort: taskSort,
243	    };
244	  }, [trimmedTaskQuery, taskActiveFilters.statuses, taskPage, taskSearchActive, taskStatusFilterActive, taskSort, taskLimit]);
245	
246	  const {
247	    results: backendTaskResults,
248	    searching: taskSearching,
249	    searchError: taskSearchError,
250	    pagination: taskPagination,
251	  } = useBackendTaskSearch(workspaceDetail.id, taskSearchParams, featureStatusMap);
252	
253	  const trimmedFeatureQuery = deferredFeatureSearchQuery.trim();
254	
255	  // Feature-mode backend search activates when search text is present OR the
256	  // status filter is a non-default subset.  All-feature-statuses-selected
257	  // means no effective filter — fall back to the workspace root payload.
258	  const featureStatusFilterActive =
259	    featureActiveFilters.statuses.length > 0 &&
260	    !isAllFeatureStatusFilterSelected(featureActiveFilters.statuses);
261	  const featureSearchActive =
262	    boardMode === "feature" &&
263	    (trimmedFeatureQuery.length > 0 || featureStatusFilterActive);
264	
265	  const prevFeatureQueryRef = useRef(trimmedFeatureQuery);
266	  const prevFeatureStatusRef = useRef(
267	    featureActiveFilters.statuses.join(","),
268	  );
269	  const prevFeatureSortRef = useRef(featureSort);
270	  const prevFeatureLimitRef = useRef(featureLimit);
271	  useEffect(() => {
272	    const currentStatus = featureActiveFilters.statuses.join(",");
273	    if (
274	      trimmedFeatureQuery !== prevFeatureQueryRef.current ||
275	      currentStatus !== prevFeatureStatusRef.current ||
276	      featureSort !== prevFeatureSortRef.current ||
277	      featureLimit !== prevFeatureLimitRef.current
278	    ) {
279	      setFeaturePage(1);
280	    }
