5	  useCallback,
6	  useContext,
7	  useEffect,
8	  useMemo,
9	  useRef,
10	  useState,
11	  type ReactNode,
12	} from "react";
13	import { useRouter } from "next/navigation";
14	import {
15	  getWorkspace,
16	  importWorkspace as apiImportWorkspace,
17	  syncWorkspace as apiSyncWorkspace,
18	  type ApiError,
19	  type ImportWorkspaceRequest,
20	  type LocalWorkspaceSummary,
21	  type WorkspaceDetail,
22	} from "@/services/workflow-backend";
23	import { buildImportLocalSummary } from "@/features/workspaces/lib/workspaceAdapter";
24	import {
25	  getLocalWorkspaceSummaries,
26	  getSelectedWorkspaceId,
27	  clearSelectedWorkspaceId,
28	  resolveBootstrapWorkspaceId,
29	  saveLocalWorkspaceSummary,
30	  removeLocalWorkspaceSummary,
31	  setSelectedWorkspaceId,
32	} from "@/services/local-workspace-store";
33	import {
34	  addTaskTab,
35	  removeTaskTab,
36	  addFeatureTab,
37	  removeFeatureTab,
38	  createTabSessionId,
39	  getTaskTabHref,
40	  getFeatureTabHref,
41	} from "@/features/workspaces/lib/tabState";
42	import { createRequestSequence } from "@/lib/request-sequence";
43	import {
44	  clearStatusFilter,
45	  clearFeatureStatusFilter,
46	  clearBoardMode,
47	} from "@/features/board/lib/status-filter-store";
48	
49	export type TaskTabEntry = {
50	  sessionId: string;
51	  workspaceId: string;
52	  taskId: string;
53	  taskName: string;
54	  title: string;
55	  featureId?: string;
56	  featureName?: string;
57	};
58	
59	export type FeatureTabEntry = {
60	  sessionId: string;
61	  workspaceId: string;
62	  featureId: string;
63	  featureName: string;
64	  title: string;
65	};
66	
67	export type WorkspaceSurface = "board" | "task-tab" | "feature-tab";
68	
69	export type TabOpenOptions = {
70	  forceNewSession?: boolean;
71	};
72	
73	export type WorkspaceContextValue = {
74	  summaries: LocalWorkspaceSummary[];
75	  selectedWorkspaceId: string | null;
76	  activeWorkspace: WorkspaceDetail | null;
77	  loadingWorkspace: boolean;
78	  workspaceError: ApiError | null;
79	  importingWorkspace: boolean;
80	  importError: ApiError | null;
81	  syncingWorkspace: boolean;
82	  syncError: ApiError | null;
83	
84	  selectWorkspace: (workspaceId: string) => void;
85	  importWorkspace: (body: ImportWorkspaceRequest) => Promise<void>;
86	  clearImportError: () => void;
87	  removeLocalSummary: (workspaceId: string) => void;
88	  syncCurrentWorkspace: () => Promise<void>;
89	  clearSyncError: () => void;
90	
91	  activeSurface: WorkspaceSurface;
92	  openTaskTabs: TaskTabEntry[];
93	  activeTaskTabId: string | null;
94	  openTaskTab: (
95	    entry: Omit<TaskTabEntry, "sessionId" | "workspaceId">,
96	    options?: TabOpenOptions,
97	  ) => void;
98	  closeTaskTab: (sessionId: string) => void;
99	  activateTaskTab: (sessionId: string) => void;
100	  markTaskTabActive: (sessionId: string) => void;
101	  openFeatureTabs: FeatureTabEntry[];
102	  activeFeatureTabId: string | null;
103	  openFeatureTab: (
104	    entry: Omit<FeatureTabEntry, "sessionId" | "workspaceId">,
105	    options?: TabOpenOptions,
106	  ) => void;
107	  closeFeatureTab: (sessionId: string) => void;
108	  activateFeatureTab: (sessionId: string) => void;
109	  markFeatureTabActive: (sessionId: string) => void;
110	  goToBoard: () => void;
111	};
112	
113	export type WorkspaceActionsContextValue = Pick<
114	  WorkspaceContextValue,
115	  | "syncCurrentWorkspace"
116	  | "syncingWorkspace"
117	  | "syncError"
118	  | "openTaskTab"
119	  | "openFeatureTab"
120	>;
121	
122	const WorkspaceContext = createContext<WorkspaceContextValue | null>(null);
123	const WorkspaceActionsContext =
124	  createContext<WorkspaceActionsContextValue | null>(null);
125	
126	export function WorkspaceProvider({ children }: { children: ReactNode }) {
127	  const router = useRouter();
128	  const [summaries, setSummaries] = useState<LocalWorkspaceSummary[]>(() =>
129	    getLocalWorkspaceSummaries(),
130	  );
131	  const [selectedWorkspaceId, setSelectedWorkspaceIdState] = useState<
132	    string | null
133	  >(() => getSelectedWorkspaceId());
134	  const [activeWorkspace, setActiveWorkspace] =
135	    useState<WorkspaceDetail | null>(null);
136	  const [loadingWorkspace, setLoadingWorkspace] = useState(() => {
137	    const storedSummaries = getLocalWorkspaceSummaries();
138	    const storedId = getSelectedWorkspaceId();
139	    return Boolean(resolveBootstrapWorkspaceId(storedSummaries, storedId));
140	  });
141	  const [workspaceError, setWorkspaceError] = useState<ApiError | null>(null);
142	  const [importingWorkspace, setImportingWorkspace] = useState(false);
143	  const [importError, setImportError] = useState<ApiError | null>(null);
144	  const [syncingWorkspace, setSyncingWorkspace] = useState(false);
145	  const [syncError, setSyncError] = useState<ApiError | null>(null);
146	
147	  const [activeSurface, setActiveSurface] = useState<WorkspaceSurface>("board");
148	  const [openTaskTabs, setOpenTaskTabs] = useState<TaskTabEntry[]>([]);
149	  const [activeTaskTabId, setActiveTaskTabId] = useState<string | null>(null);
150	  const [openFeatureTabs, setOpenFeatureTabs] = useState<FeatureTabEntry[]>([]);
151	  const [activeFeatureTabId, setActiveFeatureTabId] = useState<string | null>(
152	    null,
153	  );
154	  const openTaskTabsRef = useRef(openTaskTabs);
155	  const openFeatureTabsRef = useRef(openFeatureTabs);
156	  const loadWorkspaceSequenceRef = useRef(createRequestSequence());
157	  const didBootstrapRef = useRef(false);
158	
159	  useEffect(() => {
160	    openTaskTabsRef.current = openTaskTabs;
161	  }, [openTaskTabs]);
162	
163	  useEffect(() => {
164	    openFeatureTabsRef.current = openFeatureTabs;
165	  }, [openFeatureTabs]);
166	
167	  const isWorkspaceNotFound = useCallback((err: ApiError) => {
168	    return (
169	      err.code === "DATABASE_NOT_FOUND" ||
170	      err.code === "GITHUB_NOT_FOUND" ||
171	      err.code === "WORKSPACE_NOT_FOUND"
172	    );
173	  }, []);
174	
175	  const handleMissingWorkspace = useCallback(
176	    (workspaceId: string) => {
177	      removeLocalWorkspaceSummary(workspaceId);
178	      const updatedSummaries = getLocalWorkspaceSummaries();
179	      setSummaries(updatedSummaries);
180	
181	      if (selectedWorkspaceId === workspaceId) {
182	        clearSelectedWorkspaceId();
183	        setSelectedWorkspaceIdState(null);
184	      }
185	
186	      setActiveWorkspace(null);
187	      setWorkspaceError(null);
188	      setLoadingWorkspace(false);
189	      router.replace("/connect");
190	    },
191	    [router, selectedWorkspaceId],
192	  );
193	
194	  const loadWorkspace = useCallback(
195	    (workspaceId: string) => {
196	      const requestId = loadWorkspaceSequenceRef.current.next();
197	      setLoadingWorkspace(true);
198	      setWorkspaceError(null);
199	      getWorkspace(workspaceId)
200	        .then((detail) => {
201	          if (!loadWorkspaceSequenceRef.current.isCurrent(requestId)) return;
202	          setActiveWorkspace(detail);
203	          setLoadingWorkspace(false);
204	        })
205	        .catch((err: ApiError) => {
206	          if (!loadWorkspaceSequenceRef.current.isCurrent(requestId)) return;
207	          if (isWorkspaceNotFound(err)) {
208	            handleMissingWorkspace(workspaceId);
209	            return;
210	          }
211	          setWorkspaceError(err);
212	          setLoadingWorkspace(false);
213	        });
214	    },
215	    [handleMissingWorkspace, isWorkspaceNotFound],
216	  );
217	
218	  useEffect(() => {
219	    if (didBootstrapRef.current) return;
220	    didBootstrapRef.current = true;
221	
222	    const storedSummaries = getLocalWorkspaceSummaries();
223	    const storedId = getSelectedWorkspaceId();
224	    setSummaries(storedSummaries);
225	
226	    const workspaceId = resolveBootstrapWorkspaceId(storedSummaries, storedId);
227	
228	    if (workspaceId) {
229	      setSelectedWorkspaceIdState(workspaceId);
230	      loadWorkspace(workspaceId);
231	    } else {
232	      setLoadingWorkspace(false);
233	    }
234	  }, [loadWorkspace]);
235	
236	  const selectWorkspace = useCallback(
237	    (workspaceId: string) => {
238	      setSelectedWorkspaceIdState(workspaceId);
239	      setSelectedWorkspaceId(workspaceId);
240	      setActiveWorkspace(null);
241	
242	      // Close all open tabs — stale tabs from the previous workspace
243	      // must not survive a workspace switch.
244	      setOpenTaskTabs([]);
245	      setOpenFeatureTabs([]);
246	      setActiveTaskTabId(null);
247	      setActiveFeatureTabId(null);
248	      setActiveSurface("board");
249	
250	      // Clear board-level persisted filter/mode state so the new
251	      // BoardProvider starts with factory defaults instead of stale
252	      // values from the previous workspace.
253	      clearStatusFilter();
254	      clearFeatureStatusFilter();
255	      clearBoardMode();
256	
257	      const summary = summaries.find((s) => s.workspaceId === workspaceId);
258	      if (summary) {
259	        const updated: LocalWorkspaceSummary = {
260	          ...summary,
261	          last_opened_at: new Date().toISOString(),
262	        };
263	        saveLocalWorkspaceSummary(updated);
264	        setSummaries(getLocalWorkspaceSummaries());
265	      }
266	
267	      loadWorkspace(workspaceId);
268	    },
269	    [summaries, loadWorkspace],
270	  );
271	
272	  const importWorkspaceFn = useCallback(
273	    async (body: ImportWorkspaceRequest) => {
274	      setImportingWorkspace(true);
275	      setImportError(null);
276	      try {
277	        const detail = await apiImportWorkspace(body);
278	
279	        const summary = buildImportLocalSummary(
280	          detail,
281	          body,
282	          new Date().toISOString(),
283	        );
284	        loadWorkspaceSequenceRef.current.next();
285	        saveLocalWorkspaceSummary(summary);
286	        setSelectedWorkspaceId(detail.id);
287	        setSummaries(getLocalWorkspaceSummaries());
288	        setSelectedWorkspaceIdState(detail.id);
289	        setActiveWorkspace(detail);
290	      } catch (err) {
291	        setImportError(err as ApiError);
292	        throw err;
293	      } finally {
294	        setImportingWorkspace(false);
295	      }
296	    },
297	    [],
298	  );
299	
300	  const clearImportError = useCallback(() => {
301	    setImportError(null);
302	  }, []);
303	
304	  const syncCurrentWorkspace = useCallback(async () => {
305	    if (!selectedWorkspaceId) return;
306	    setSyncingWorkspace(true);
307	    setSyncError(null);
308	    try {
309	      const detail = await apiSyncWorkspace(selectedWorkspaceId);
310	      setActiveWorkspace(detail);
311	    } catch (err) {
312	      const apiError = err as ApiError;
313	      if (isWorkspaceNotFound(apiError)) {
314	        handleMissingWorkspace(selectedWorkspaceId);
315	        return;
316	      }
317	      setSyncError(apiError);
318	      throw err;
319	    } finally {
320	      setSyncingWorkspace(false);
321	    }
322	  }, [handleMissingWorkspace, isWorkspaceNotFound, selectedWorkspaceId]);
323	
324	  const clearSyncError = useCallback(() => {
325	    setSyncError(null);
326	  }, []);
327	
328	  const removeLocalSummary = useCallback(
329	    (workspaceId: string) => {
330	      removeLocalWorkspaceSummary(workspaceId);
331	      setSummaries(getLocalWorkspaceSummaries());
332	      if (selectedWorkspaceId === workspaceId) {
333	        const remaining = getLocalWorkspaceSummaries();
334	        const next = remaining[0] ?? null;
335	        if (next) {
336	          setSelectedWorkspaceIdState(next.workspaceId);
337	          setSelectedWorkspaceId(next.workspaceId);
338	          loadWorkspace(next.workspaceId);
339	        } else {
340	          setSelectedWorkspaceIdState(null);
341	          setActiveWorkspace(null);
342	        }
343	      }
344	    },
345	    [selectedWorkspaceId, loadWorkspace],
346	  );
347	
348	  const openTaskTab = useCallback(
349	    (
350	      entry: Omit<TaskTabEntry, "sessionId" | "workspaceId">,
351	      options?: TabOpenOptions,
352	    ) => {
353	      const workspaceId = selectedWorkspaceId ?? activeWorkspace?.id;
354	      if (!workspaceId) return;
355	      if (!options?.forceNewSession) {
356	        const existing = openTaskTabsRef.current.find(
357	          (tab) =>
358	            tab.taskId === entry.taskId && tab.workspaceId === workspaceId,
359	        );
360	        if (existing) {
361	          setActiveTaskTabId(existing.sessionId);
362	          setActiveSurface("task-tab");
363	          router.push(getTaskTabHref(existing));
364	          return;
365	        }
366	      }
367	      const tab: TaskTabEntry = {
368	        ...entry,
369	        workspaceId,
370	        sessionId: createTabSessionId("task"),
371	      };
372	      setOpenTaskTabs((prev) => addTaskTab(prev, tab));
373	      setActiveTaskTabId(tab.sessionId);
374	      setActiveSurface("task-tab");
375	      router.push(getTaskTabHref(tab));
376	    },
377	    [activeWorkspace?.id, router, selectedWorkspaceId],
378	  );
379	
380	  const closeTaskTab = useCallback(
381	    (sessionId: string) => {
382	      setOpenTaskTabs((prev) => removeTaskTab(prev, sessionId));
383	      if (activeTaskTabId === sessionId) {
384	        setActiveTaskTabId(null);
385	        setActiveSurface("board");
386	        router.push("/board");
387	      }
388	    },
389	    [activeTaskTabId, router],
390	  );
391	
392	  const activateTaskTab = useCallback(
393	    (sessionId: string) => {
394	      const tab = openTaskTabs.find((entry) => entry.sessionId === sessionId);
395	      if (!tab) return;
396	      setActiveTaskTabId(sessionId);
397	      setActiveSurface("task-tab");
398	      router.push(getTaskTabHref(tab));
399	    },
400	    [openTaskTabs, router],
401	  );
402	
403	  const markTaskTabActive = useCallback((sessionId: string) => {
404	    setActiveTaskTabId(sessionId);
405	    setActiveFeatureTabId(null);
406	    setActiveSurface("task-tab");
407	  }, []);
408	
409	  const openFeatureTab = useCallback(
410	    (
411	      entry: Omit<FeatureTabEntry, "sessionId" | "workspaceId">,
412	      options?: TabOpenOptions,
413	    ) => {
414	      const workspaceId = selectedWorkspaceId ?? activeWorkspace?.id;
415	      if (!workspaceId) return;
416	      if (!options?.forceNewSession) {
417	        const existing = openFeatureTabsRef.current.find(
418	          (tab) =>
419	            tab.featureId === entry.featureId &&
420	            tab.workspaceId === workspaceId,
421	        );
422	        if (existing) {
423	          setActiveFeatureTabId(existing.sessionId);
424	          setActiveSurface("feature-tab");
425	          router.push(getFeatureTabHref(existing));
426	          return;
427	        }
428	      }
429	      const tab: FeatureTabEntry = {
430	        ...entry,
431	        workspaceId,
432	        sessionId: createTabSessionId("feature"),
433	      };
434	      setOpenFeatureTabs((prev) => addFeatureTab(prev, tab));
435	      setActiveFeatureTabId(tab.sessionId);
436	      setActiveSurface("feature-tab");
437	      router.push(getFeatureTabHref(tab));
438	    },
439	    [activeWorkspace?.id, router, selectedWorkspaceId],
440	  );
441	
442	  const closeFeatureTab = useCallback(
443	    (sessionId: string) => {
444	      setOpenFeatureTabs((prev) => removeFeatureTab(prev, sessionId));
445	      if (activeFeatureTabId === sessionId) {
446	        setActiveFeatureTabId(null);
447	        setActiveSurface("board");
448	        router.push("/board");
449	      }
450	    },
451	    [activeFeatureTabId, router],
452	  );
453	
454	  const activateFeatureTab = useCallback(
455	    (sessionId: string) => {
456	      const tab = openFeatureTabs.find(
457	        (entry) => entry.sessionId === sessionId,
458	      );
459	      if (!tab) return;
460	      setActiveFeatureTabId(sessionId);
461	      setActiveSurface("feature-tab");
462	      router.push(getFeatureTabHref(tab));
463	    },
464	    [openFeatureTabs, router],
465	  );
466	
467	  const markFeatureTabActive = useCallback((sessionId: string) => {
468	    setActiveFeatureTabId(sessionId);
469	    setActiveTaskTabId(null);
470	    setActiveSurface("feature-tab");
471	  }, []);
472	
473	  const goToBoard = useCallback(() => {
474	    setActiveSurface("board");
475	    setActiveTaskTabId(null);
476	    setActiveFeatureTabId(null);
477	    router.push("/board");
478	  }, [router]);
479	
480	  const value = useMemo<WorkspaceContextValue>(
481	    () => ({
482	      summaries,
483	      selectedWorkspaceId,
484	      activeWorkspace,
485	      loadingWorkspace,
486	      workspaceError,
487	      importingWorkspace,
488	      importError,
489	      syncingWorkspace,
490	      syncError,
491	      selectWorkspace,
492	      importWorkspace: importWorkspaceFn,
493	      clearImportError,
494	      removeLocalSummary,
495	      syncCurrentWorkspace,
496	      clearSyncError,
497	      activeSurface,
498	      openTaskTabs,
499	      activeTaskTabId,
500	      openTaskTab,
501	      closeTaskTab,
502	      activateTaskTab,
503	      markTaskTabActive,
504	      openFeatureTabs,
505	      activeFeatureTabId,
506	      openFeatureTab,
507	      closeFeatureTab,
508	      activateFeatureTab,
509	      markFeatureTabActive,
510	      goToBoard,
511	    }),
512	    [
513	      summaries,
514	      selectedWorkspaceId,
515	      activeWorkspace,
516	      loadingWorkspace,
517	      workspaceError,
518	      importingWorkspace,
519	      importError,
520	      syncingWorkspace,
521	      syncError,
522	      selectWorkspace,
523	      importWorkspaceFn,
524	      clearImportError,
525	      removeLocalSummary,
526	      syncCurrentWorkspace,
527	      clearSyncError,
528	      activeSurface,
529	      openTaskTabs,
530	      activeTaskTabId,
531	      openTaskTab,
532	      closeTaskTab,
533	      activateTaskTab,
534	      markTaskTabActive,
535	      openFeatureTabs,
536	      activeFeatureTabId,
537	      openFeatureTab,
538	      closeFeatureTab,
539	      activateFeatureTab,
540	      markFeatureTabActive,
541	      goToBoard,
542	    ],
543	  );
544	
545	  const actionsValue = useMemo<WorkspaceActionsContextValue>(
546	    () => ({
547	      syncCurrentWorkspace,
548	      syncingWorkspace,
549	      syncError,
550	      openTaskTab,
551	      openFeatureTab,
552	    }),
553	    [
554	      syncCurrentWorkspace,
555	      syncingWorkspace,
556	      syncError,
557	      openTaskTab,
558	      openFeatureTab,
559	    ],
560	  );
561	
562	  return (
563	    <WorkspaceContext.Provider value={value}>
564	      <WorkspaceActionsContext.Provider value={actionsValue}>
565	        {children}
566	      </WorkspaceActionsContext.Provider>
567	    </WorkspaceContext.Provider>
568	  );
569	}
570	
571	export function useWorkspaceContext(): WorkspaceContextValue {
572	  const ctx = useContext(WorkspaceContext);
573	  if (!ctx) {
574	    throw new Error(
575	      "useWorkspaceContext must be used within a WorkspaceProvider",
576	    );
577	  }
578	  return ctx;
579	}
580	
581	export function useWorkspaceActionsContext(): WorkspaceActionsContextValue {
582	  const ctx = useContext(WorkspaceActionsContext);
583	  if (!ctx) {
584	    throw new Error(
585	      "useWorkspaceActionsContext must be used within a WorkspaceProvider",
586	    );
587	  }
588	  return ctx;
589	}
