      clearImportError,
      removeLocalSummary,
      syncCurrentWorkspace,
      clearSyncError,
      activeSurface,
      openTaskTabs,
      activeTaskTabId,
      openTaskTab,
      closeTaskTab,
      activateTaskTab,
      markTaskTabActive,
      openFeatureTabs,
      activeFeatureTabId,
      openFeatureTab,
      closeFeatureTab,
      activateFeatureTab,
      markFeatureTabActive,
      goToBoard,
    }),
    [
      summaries,
      selectedWorkspaceId,
      activeWorkspace,
      loadingWorkspace,
      workspaceError,
      importingWorkspace,
      importError,
      syncingWorkspace,
      syncError,
      selectWorkspace,
