"use client";

import { useCallback, useRef } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { getWorkspace } from "@/services/workflow-backend";
import type { WorkspaceDetail } from "@/services/workflow-backend";
import type { ParsedFeature } from "@/services/yaml-parser";
import { adaptWorkspaceDetail } from "@/features/workspaces/lib/workspaceAdapter";
import type { BoardLoadError } from "../types";
import { mapApiBoardError } from "../lib/error-utils";
import { workspaceKeys } from "@/lib/query-keys";

export type UseBoardDataResult = {
  features: ParsedFeature[];
  loading: boolean;
  error: BoardLoadError | null;
  reload: () => void;
};

export type UseBoardDataOptions = {
  initialData?: WorkspaceDetail;
};

export function useBoardData(
  workspaceId: string | null,
  options: UseBoardDataOptions = {},
): UseBoardDataResult {
  const { initialData } = options;
  const queryClient = useQueryClient();
  // Capture the timestamp once when the hook first mounts so initialData is
  // treated as fresh for the full stale-time window without calling Date.now()
  // on every render (which would violate react-hooks/purity).
  const initialDataUpdatedAtRef = useRef<number | undefined>(
    initialData ? Date.now() : undefined,
  );
  if (initialData && initialDataUpdatedAtRef.current === undefined) {
    initialDataUpdatedAtRef.current = Date.now();
  }

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: workspaceKeys.detail(workspaceId ?? ""),
    queryFn: () => getWorkspace(workspaceId!),
    enabled: workspaceId !== null,
    initialData: initialData ?? undefined,
    initialDataUpdatedAt: initialDataUpdatedAtRef.current,
  });

  const reload = useCallback(() => {
    if (!workspaceId) return;
    queryClient.invalidateQueries({ queryKey: workspaceKeys.detail(workspaceId) });
    refetch();
  }, [workspaceId, queryClient, refetch]);

  if (!workspaceId) {
    return { features: [], loading: false, error: null, reload };
  }

  const features = data ? adaptWorkspaceDetail(data) : [];
  const loading = isLoading;
  const boardError = error ? mapApiBoardError(error) : null;

  return { features, loading, error: boardError, reload };
}

